use crate::dat::checksum;
use crate::error::{FlightReaderError, Result};

/// Synchronization magic byte for all DJI `.DAT` blackbox frames (`0x55` / `85` decimal).
pub const DAT_MAGIC: u8 = 0x55;

/// Length of the fixed frame header in bytes (Magic, Length, Sequence, PayloadID, Timestamp).
pub const HEADER_LEN: usize = 9;

/// The checksum verification algorithm utilized by a `.DAT` telemetry frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DatChecksumType {
    /// 16-bit CCITT checksum (2 bytes). Used by standard sensor frames (IMU, GPS, Battery).
    Crc16,
    /// 32-bit IEEE 802.3 checksum (4 bytes). Used by extended multi-sector frames.
    Crc32,
}

impl DatChecksumType {
    /// Returns the length of the checksum field in bytes (2 for CRC16, 4 for CRC32).
    #[inline]
    pub const fn checksum_len(&self) -> usize {
        match self {
            DatChecksumType::Crc16 => 2,
            DatChecksumType::Crc32 => 4,
        }
    }

    /// Returns the minimum physical frame length in bytes for this checksum type
    /// (9-byte header + checksum length).
    #[inline]
    pub const fn min_frame_len(&self) -> usize {
        HEADER_LEN + self.checksum_len()
